using Clock=std::chrono::steady_clock;
struct R{uint64_t units;double sec,rate;uint64_t ck;};
static double now(){return std::chrono::duration<double>(Clock::now().time_since_epoch()).count();}
static double med(double a[7]){std::sort(a,a+7);return a[3];}
static uint32_t mix32(uint32_t x){x+=0x9e3779b9u;x^=x>>16;x*=0x85ebca6bu;x^=x>>13;x*=0xc2b2ae35u;return x^(x>>16);}
static uint32_t hash32(uint32_t x){x^=x>>16;x*=0x7feb352du;x^=x>>15;x*=0x846ca68bu;return x^(x>>16);}
