static uint32_t ck64(const uint64_t*a,size_t n){uint32_t h=2166136261u;for(size_t i=0;i<n;i++){h=(h^(uint32_t)a[i])*16777619u;h=(h^(uint32_t)(a[i]>>32))*16777619u;}return h;}
