static R bi(uint64_t n){(void)integer50(n/20+1);double t[7];uint64_t c=0;for(int r=0;r<7;r++){double a=now();c=integer50(n);t[r]=now()-a;}double m=med(t);return{n,m,n/m/1e6,c};}
static const uint8_t PAT[23]={97,108,112,104,97,34,98,101,116,97,92,103,97,109,109,97,10,9,1,120,121,122,47};
static size_t je(const uint8_t*in,size_t n,uint8_t*out){static const char*hx="0123456789abcdef";size_t j=0;out[j++]=34;for(size_t i=0;i<n;i++){uint8_t c=in[i];switch(c){case 34:out[j++]=92;out[j++]=34;break;case 92:out[j++]=92;out[j++]=92;break;case 8:out[j++]=92;out[j++]=98;break;case 12:out[j++]=92;out[j++]=102;break;case 10:out[j++]=92;out[j++]=110;break;case 13:out[j++]=92;out[j++]=114;break;case 9:out[j++]=92;out[j++]=116;break;default:if(c<32){out[j++]=92;out[j++]=117;out[j++]=48;out[j++]=48;out[j++]=hx[c>>4];out[j++]=hx[c&15];}else out[j++]=c;}}out[j++]=34;return j;}
static R bj(uint64_t nu){size_t n=nu;auto*in=(uint8_t*)malloc(n);auto*out=(uint8_t*)malloc(n*6+2);for(size_t i=0;i<n;i++)in[i]=PAT[i%23];size_t on=je(in,n,out);double t[7];for(int r=0;r<7;r++){double a=now();on=je(in,n,out);t[r]=now()-a;}uint64_t c=on;for(size_t i=0;i<on;i++)c+=out[i];double m=med(t);free(out);free(in);return{nu,m,n/m/1e9,c};}
static void ms(uint32_t*a,uint32_t*tmp,size_t n){uint32_t*s=a,*d=tmp;int flip=0;for(size_t w=1;w<n;w*=2){for(size_t lo=0;lo<n;lo+=2*w){size_t mid=std::min(lo+w,n),hi=std::min(lo+2*w,n),i=lo,j=mid,k=lo;while(i<mid&&j<hi)d[k++]=s[i]<=s[j]?s[i++]:s[j++];while(i<mid)d[k++]=s[i++];while(j<hi)d[k++]=s[j++];}std::swap(s,d);flip^=1;if(w>n/2)break;}if(flip)memcpy(a,s,n*4);}
static R bm(uint64_t nu){size_t n=nu;auto*base=(uint32_t*)malloc(n*4);auto*a=(uint32_t*)malloc(n*4);auto*tmp=(uint32_t*)malloc(n*4);for(size_t i=0;i<n;i++)base[i]=mix32(i);double t[7];for(int r=0;r<7;r++){memcpy(a,base,n*4);double q=now();ms(a,tmp,n);t[r]=now()-q;}double m=med(t);uint32_t c=ck32(a,n);free(tmp);free(a);free(base);return{nu,m,n/m/1e6,c};}
static int32_t bs(const uint32_t*a,size_t n,uint32_t x){size_t l=0,h=n;while(l<h){size_t m=l+(h-l)/2;if(a[m]<x)l=m+1;else h=m;}return l<n&&a[l]==x?(int32_t)l:-1;}
static R bbs(uint64_t nu){size_t n=nu,nq=n*4;auto*a=(uint32_t*)malloc(n*4);auto*q=(uint32_t*)malloc(nq*4);for(size_t i=0;i<n;i++)a[i]=i*2;for(size_t i=0;i<nq;i++)q[i]=mix32(i)%(2*n);double t[7];uint64_t c=0;for(int r=0;r<7;r++){double s=now();c=0;for(size_t i=0;i<nq;i++){int32_t p=bs(a,n,q[i]);if(p>=0)c+=(uint32_t)p+1;}t[r]=now()-s;}double m=med(t);free(q);free(a);return{nq,m,nq/m/1e6,c};}
static R bps(uint64_t nu){size_t n=nu;auto*in=(uint32_t*)malloc(n*4);auto*out=(uint64_t*)malloc(n*8);for(size_t i=0;i<n;i++)in[i]=mix32(i)&1023;double t[7];uint32_t c=0;for(int r=0;r<7;r++){double s0=now();c=0;for(int z=0;z<16;z++){uint64_t s=z;for(size_t i=0;i<n;i++){s+=in[i];out[i]=s;}c^=(uint32_t)s;}t[r]=now()-s0;}c^=ck64(out,n);double m=med(t);free(out);free(in);return{nu*16,m,n*16.0/m/1e6,c};}
static R bmm(uint64_t nu){size_t n=nu,nn=n*n;auto*a=(uint32_t*)malloc(nn*4);auto*b=(uint32_t*)malloc(nn*4);auto*c=(uint64_t*)malloc(nn*8);for(size_t i=0;i<nn;i++){a[i]=mix32(i)&15;b[i]=mix32(i+nn)&15;}double t[7];for(int r=0;r<7;r++){double s0=now();for(size_t i=0;i<n;i++)for(size_t j=0;j<n;j++){uint64_t s=0;for(size_t k=0;k<n;k++)s+=(uint64_t)a[i*n+k]*b[k*n+j];c[i*n+j]=s;}t[r]=now()-s0;}double m=med(t);uint32_t ck=ck64(c,nn);free(c);free(b);free(a);return{nu,m,(double)n*n*n/m/1e6,ck};}
static void graph(uint32_t*a,uint32_t*w,size_t n,int d){for(size_t i=0;i<n;i++)for(int e=0;e<d;e++){size_t p=i*d+e;a[p]=e==0?(i+1)%n:e==1?(i+n-1)%n:mix32(p)%n;if(w)w[p]=1+(mix32(0xabc00000u+(uint32_t)p)&15);}}
static R bbfs(uint64_t nu){const int d=4,passes=16;size_t n=nu;auto*a=(uint32_t*)malloc(n*d*4);auto*q=(uint32_t*)malloc(n*4);auto*dist=(int32_t*)malloc(n*4);graph(a,nullptr,n,d);double t[7];uint32_t seen=0;for(int r=0;r<7;r++){double s0=now();for(int z=0;z<passes;z++){for(size_t i=0;i<n;i++)dist[i]=-1;size_t h=0,tt=0;dist[0]=0;q[tt++]=0;while(h<tt){uint32_t u=q[h++];int32_t nd=dist[u]+1;for(int e=0;e<d;e++){uint32_t v=a[(size_t)u*d+e];if(dist[v]<0){dist[v]=nd;q[tt++]=v;}}}seen^=(uint32_t)tt+(uint32_t)z;}t[r]=now()-s0;}double m=med(t);uint32_t c=ck32((uint32_t*)dist,n)^seen;free(dist);free(q);free(a);return{nu*passes,m,n*d*passes/(m*1e6),c};}
struct HP{uint64_t d;uint32_t v;};
static void hpp(HP*h,size_t&sz,HP x){size_t i=sz++;while(i){size_t p=(i-1)/2;if(h[p].d<=x.d)break;h[i]=h[p];i=p;}h[i]=x;}
static HP hpo(HP*h,size_t&sz){HP o=h[0],x=h[--sz];size_t i=0;while(true){size_t l=i*2+1;if(l>=sz)break;size_t r=l+1,c=r<sz&&h[r].d<h[l].d?r:l;if(h[c].d>=x.d)break;h[i]=h[c];i=c;}if(sz)h[i]=x;return o;}
static R bdij(uint64_t nu){const int d=4;size_t n=nu;auto*a=(uint32_t*)malloc(n*d*4);auto*w=(uint32_t*)malloc(n*d*4);auto*dist=(uint64_t*)malloc(n*8);auto*h=(HP*)malloc(n*d*4*sizeof(HP));graph(a,w,n,d);double t[7];uint32_t c=0;for(int r=0;r<7;r++){double s0=now();for(size_t i=0;i<n;i++)dist[i]=UINT64_MAX/4;size_t sz=0;dist[0]=0;hpp(h,sz,{0,0});while(sz){HP x=hpo(h,sz);if(x.d!=dist[x.v])continue;for(int e=0;e<d;e++){size_t p=(size_t)x.v*d+e;uint32_t v=a[p];uint64_t nd=x.d+w[p];if(nd<dist[v]){dist[v]=nd;hpp(h,sz,{nd,v});}}}c=ck64(dist,n);t[r]=now()-s0;}double m=med(t);free(h);free(dist);free(w);free(a);return{nu,m,n*d/(m*1e6),c};}
static uint32_t uff(uint32_t*p,uint32_t x){while(p[x]!=x){p[x]=p[p[x]];x=p[x];}return x;}
static R buf(uint64_t nu){size_t n=nu,ops=n*4;auto*p=(uint32_t*)malloc(n*4);auto*rank=(uint8_t*)malloc(n);auto*A=(uint32_t*)malloc(ops*4);auto*B=(uint32_t*)malloc(ops*4);for(size_t i=0;i<ops;i++){A[i]=mix32(i)%n;B[i]=mix32(i+ops)%n;}double t[7];for(int r=0;r<7;r++){double s0=now();for(size_t i=0;i<n;i++){p[i]=i;rank[i]=0;}for(size_t i=0;i<ops;i++){uint32_t ra=uff(p,A[i]),rb=uff(p,B[i]);if(ra!=rb){if(rank[ra]<rank[rb])std::swap(ra,rb);p[rb]=ra;if(rank[ra]==rank[rb])rank[ra]++;}}t[r]=now()-s0;}for(size_t i=0;i<n;i++)p[i]=uff(p,i);uint32_t c=ck32(p,n);double m=med(t);free(B);free(A);free(rank);free(p);return{ops,m,ops/(m*1e6),c};}
static uint64_t mandel(int w,int mi){uint64_t s=0;for(int y=0;y<w;y++){double ci=-1.5+3.0*y/(w-1.0);for(int x=0;x<w;x++){double cr=-2+3.0*x/(w-1.0),zr=0,zi=0;int it=0;while(it<mi){double a=zr*zr,b=zi*zi;if(a+b>4)break;double nz=a-b+cr;zi=2*zr*zi+ci;zr=nz;it++;}s+=it;}}return s;}
static R bman(uint64_t wu){int w=wu;(void)mandel(std::min(w,128),20);double t[7];uint64_t c=0;for(int r=0;r<7;r++){double s0=now();c=mandel(w,50);t[r]=now()-s0;}double m=med(t);return{wu*wu,m,wu*wu/(m*1e6),c};}
struct V{uint32_t*p=nullptr;size_t n=0,cap=0;void push(uint32_t x){if(n==cap){size_t nc=cap?cap*2:8;p=(uint32_t*)realloc(p,nc*4);cap=nc;}p[n++]=x;}};
static R bva(uint64_t nu){size_t n=nu;auto*in=(uint32_t*)malloc(n*4);for(size_t i=0;i<n;i++)in[i]=mix32(i);double t[7];uint32_t c=0;for(int r=0;r<7;r++){double s0=now();V v;for(size_t i=0;i<n;i++)v.push(in[i]);uint32_t h=2166136261u;for(size_t i=0;i<n;i++){v.p[i]^=(uint32_t)i;h=(h^v.p[i])*16777619u;}while(v.n){uint32_t x=v.p[--v.n];h=(h^(x+(uint32_t)v.n))*16777619u;}free(v.p);c=h;t[r]=now()-s0;}double m=med(t);free(in);return{nu,m,n/m/1e6,c};}
static R bll(uint64_t nu){const int passes=16;size_t n=nu;auto*next=(uint32_t*)malloc(n*4);auto*val=(uint32_t*)malloc(n*4);auto*base=(uint32_t*)malloc(n*4);for(size_t i=0;i<n;i++)base[i]=mix32(i);double t[7];uint32_t c=0;for(int r=0;r<7;r++){double s0=now();memcpy(val,base,n*4);for(size_t i=0;i<n;i++)next[i]=i+1<n?i+1:UINT32_MAX;const size_t B=64;for(size_t b=0;b<n;b+=B){size_t hi=std::min(b+B,n)-1;for(size_t i=b;i<=hi;i++)next[i]=i==b?(hi+1<n?hi+1:UINT32_MAX):i-1;}uint32_t h=2166136261u;for(int p=0;p<passes;p++){uint32_t cur=B<n?B-1:n-1;size_t seen=0;while(cur!=UINT32_MAX&&seen<n){val[cur]^=(uint32_t)(seen+p);h=(h^(val[cur]+cur+(uint32_t)p))*16777619u;cur=next[cur];seen++;}h=(h^(uint32_t)seen)*16777619u;}c=h;t[r]=now()-s0;}double m=med(t);free(base);free(val);free(next);return{nu*passes,m,n*passes/(m*1e6),c};}
static R bqr(uint64_t ou){size_t ops=ou,cap=ops/2+1024;auto*b=(uint32_t*)malloc(cap*4);auto*in=(uint32_t*)malloc(ops*4);for(size_t i=0;i<ops;i++)in[i]=mix32(i);double t[7];uint32_t c=0;for(int r=0;r<7;r++){double s0=now();size_t h=0,tt=0,cnt=0;uint32_t z=0;for(size_t i=0;i<ops;i++){if((i&3)!=3){if(cnt==cap){z^=b[h];h=(h+1)%cap;cnt--;}b[tt]=in[i];tt=(tt+1)%cap;cnt++;}else if(cnt){z^=b[h];h=(h+1)%cap;cnt--;}}while(cnt){z^=b[h];h=(h+1)%cap;cnt--;}c=z;t[r]=now()-s0;}double m=med(t);free(in);free(b);return{ou,m,ops/(m*1e6),c};}
static size_t np2(size_t x){size_t p=1;while(p<x)p<<=1;return p;}
static R bht(uint64_t nu){size_t n=nu,cap=np2(n*2),mask=cap-1;auto*k=(uint32_t*)calloc(cap,4);auto*v=(uint32_t*)malloc(cap*4);auto*ik=(uint32_t*)malloc(n*4);auto*iv=(uint32_t*)malloc(n*4);for(size_t i=0;i<n;i++){ik[i]=mix32(i)|1;iv[i]=mix32(i+0x55555555u);}double t[7];uint32_t c=0;for(int r=0;r<7;r++){double s0=now();memset(k,0,cap*4);for(size_t i=0;i<n;i++){uint32_t key=ik[i];size_t p=hash32(key)&mask;while(k[p]&&k[p]!=key)p=(p+1)&mask;k[p]=key;v[p]=iv[i];}uint32_t h=0;for(size_t i=0;i<n;i++){uint32_t key=ik[i];size_t p=hash32(key)&mask;while(k[p]!=key)p=(p+1)&mask;v[p]^=(uint32_t)i;h^=v[p];}c=h;t[r]=now()-s0;}double m=med(t);free(iv);free(ik);free(v);free(k);return{nu,m,n*2/(m*1e6),c};}
static void hp32(uint32_t*h,size_t&sz,uint32_t x){size_t i=sz++;while(i){size_t p=(i-1)/2;if(h[p]<=x)break;h[i]=h[p];i=p;}h[i]=x;}
static uint32_t ho32(uint32_t*h,size_t&sz){uint32_t o=h[0],x=h[--sz];size_t i=0;while(true){size_t l=i*2+1;if(l>=sz)break;size_t r=l+1,c=r<sz&&h[r]<h[l]?r:l;if(h[c]>=x)break;h[i]=h[c];i=c;}if(sz)h[i]=x;return o;}
static R bbh(uint64_t nu){size_t n=nu;auto*h=(uint32_t*)malloc(n*4);auto*in=(uint32_t*)malloc(n*4);for(size_t i=0;i<n;i++)in[i]=mix32(i);double t[7];uint32_t c=0;for(int r=0;r<7;r++){double s0=now();size_t sz=0;for(size_t i=0;i<n;i++)hp32(h,sz,in[i]);uint32_t z=0;for(size_t i=0;i<n;i++)z^=ho32(h,sz)+(uint32_t)i;c=z;t[r]=now()-s0;}double m=med(t);free(in);free(h);return{nu,m,n*2/(m*1e6),c};}
static R bbst(uint64_t nu){size_t n=nu;auto*k=(uint32_t*)malloc(n*4);auto*in=(uint32_t*)malloc(n*4);auto*l=(int32_t*)malloc(n*4);auto*rr=(int32_t*)malloc(n*4);for(size_t i=0;i<n;i++)in[i]=mix32(i);double t[7];uint32_t c=0;for(int r=0;r<7;r++){double s0=now();int32_t root=-1;for(size_t i=0;i<n;i++){uint32_t key=in[i];k[i]=key;l[i]=rr[i]=-1;int32_t node=i;if(root<0){root=node;continue;}int32_t cur=root;while(true){if(key<k[cur]){if(l[cur]<0){l[cur]=node;break;}cur=l[cur];}else{if(rr[cur]<0){rr[cur]=node;break;}cur=rr[cur];}}}uint32_t h=0;for(size_t i=0;i<n;i+=3){uint32_t key=in[i];int32_t cur=root;while(cur>=0&&k[cur]!=key)cur=key<k[cur]?l[cur]:rr[cur];if(cur>=0)h^=(uint32_t)cur+1;}c=h;t[r]=now()-s0;}double m=med(t);free(rr);free(l);free(in);free(k);return{nu,m,n/(m*1e6),c};}
static R btr(uint64_t nu){const int passes=32;size_t n=nu,mx=1+n*8;auto*ch=(int32_t*)malloc(mx*16*4);auto*term=(uint8_t*)malloc(mx);auto*words=(uint32_t*)malloc(n*4);for(size_t i=0;i<n;i++)words[i]=mix32(i);double t[7];uint32_t c=0;for(int r=0;r<7;r++){double s0=now();for(size_t i=0;i<mx*16;i++)ch[i]=-1;memset(term,0,mx);size_t used=1;for(size_t i=0;i<n;i++){uint32_t w=words[i];int32_t node=0;for(int sh=28;sh>=0;sh-=4){int cc=(w>>sh)&15;int32_t&v=ch[(size_t)node*16+cc];if(v<0)v=used++;node=v;}term[node]=1;}uint32_t h=used;for(int p=0;p<passes;p++)for(size_t i=0;i<n;i+=2){uint32_t w=words[i];int32_t node=0;for(int sh=28;sh>=0&&node>=0;sh-=4)node=ch[(size_t)node*16+((w>>sh)&15)];if(node>=0&&term[node])h^=(uint32_t)node+1+(uint32_t)p;}c=h;t[r]=now()-s0;}double m=med(t);free(words);free(term);free(ch);return{nu*passes,m,n*passes/(m*1e6),c};}
static uint64_t ds(const std::string&k){if(k=="integer50")return 200000000;if(k=="json_escape")return 16000000;if(k=="merge_sort"||k=="binary_search"||k=="union_find"||k=="hash_table"||k=="binary_heap")return 1000000;if(k=="prefix_sum")return 8000000;if(k=="matrix_mul")return 320;if(k=="bfs")return 200000;if(k=="dijkstra"||k=="trie")return 100000;if(k=="mandelbrot")return 1600;if(k=="dynamic_array")return 5000000;if(k=="linked_list")return 4000000;if(k=="queue_ring")return 10000000;if(k=="bst")return 300000;throw std::runtime_error("unknown kernel");}
static nb::tuple run(const std::string&k,uint64_t n=0){if(!n)n=ds(k);R r;if(k=="integer50")r=bi(n);else if(k=="json_escape")r=bj(n);else if(k=="merge_sort")r=bm(n);else if(k=="binary_search")r=bbs(n);else if(k=="prefix_sum")r=bps(n);else if(k=="matrix_mul")r=bmm(n);else if(k=="bfs")r=bbfs(n);else if(k=="dijkstra")r=bdij(n);else if(k=="union_find")r=buf(n);else if(k=="mandelbrot")r=bman(n);else if(k=="dynamic_array")r=bva(n);else if(k=="linked_list")r=bll(n);else if(k=="queue_ring")r=bqr(n);else if(k=="hash_table")r=bht(n);else if(k=="binary_heap")r=bbh(n);else if(k=="bst")r=bbst(n);else if(k=="trie")r=btr(n);else throw std::runtime_error("unknown kernel");return nb::make_tuple(k,r.units,r.sec,r.rate,r.ck);}
NB_MODULE(bench_ext,m){m.def("run",&run,nb::arg("kernel"),nb::arg("size")=0);}
